from ref import Topo

def rust(code, args):
    out = subprocess.run(['/workspace/dev/dump', str(code)] + [str(a) for a in args] + [0]*(7-len(args)),
                         capture_output=True, check=True).stdout.decode().splitlines()
    n, t = map(int, out[0].split('\t'))
    rows=[]
    for line in out[2:]:
        src,dst,fp = line.split('\t')
        rows.append((int(src),int(dst),frozenset(int(x) for x in fp.split() if x)))
    assert len(rows)==t
    return n, rows

